const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artikeliai</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Vokiškas artikelis ne visada sutampa su lietuvių kalbos gimine. Todėl daiktavardžius geriausia mokytis kartu su artikeliu.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Artikelių pavyzdžiai</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — stalas</div>\n      <div class=\"kurss-example\">die Tür — durys</div>\n      <div class=\"kurss-example\">das Messer — peilis</div>\n      <div class=\"kurss-example\">das Mädchen — mergaitė</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Dažnai DER</h4>\n    <p class=\"artikuli-explain\">DER dažnai vartojamas su vyriškosios lyties asmenimis, savaitės dienomis, mėnesiais, metų laikais ir kai kuriais žodžiais su tam tikromis galūnėmis.</p>\n\n    <h5 class=\"artikuli-subtitle\">Taisyklės</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → dažnai DER, pavyzdžiui: der Computer, der Lehrer <span class=\"artikuli-note\">bet ne visada</span></div>\n      <div class=\"kurss-example\">-ling → dažnai DER, pavyzdžiui: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → dažnai DER, pavyzdžiui: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">vyriškosios lyties asmenys → der Mann, der Vater</div>\n      <div class=\"kurss-example\">profesijos → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">automobilių markės → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">savaitės dienos → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">mėnesiai → der August, der Dezember</div>\n      <div class=\"kurss-example\">metų laikai → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Pavyzdžiai</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — vyras</div>\n      <div class=\"kurss-example\">der Vater — tėvas</div>\n      <div class=\"kurss-example\">der Montag — pirmadienis</div>\n      <div class=\"kurss-example\">der August — rugpjūtis</div>\n      <div class=\"kurss-example\">der Sommer — vasara</div>\n      <div class=\"kurss-example\">der Lehrer — mokytojas</div>\n      <div class=\"kurss-example\">der Computer — kompiuteris</div>\n      <div class=\"kurss-example\">der Schmetterling — drugelis</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Dažnai DIE</h4>\n    <p class=\"artikuli-explain\">DIE dažnai vartojamas su moteriškosios lyties asmenimis, daugiskaita ir žodžiais su galūnėmis -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Taisyklės</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">moteriškosios lyties asmenys → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motociklų markės → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">daugiskaita → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">daugiskaita beveik visada → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Pavyzdžiai</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — moteris</div>\n      <div class=\"kurss-example\">die Mutter — motina</div>\n      <div class=\"kurss-example\">die Wohnung — butas</div>\n      <div class=\"kurss-example\">die Rechnung — sąskaita</div>\n      <div class=\"kurss-example\">die Freiheit — laisvė</div>\n      <div class=\"kurss-example\">die Möglichkeit — galimybė</div>\n      <div class=\"kurss-example\">die Mannschaft — komanda</div>\n      <div class=\"kurss-example\">die Nation — tauta</div>\n      <div class=\"kurss-example\">die Universität — universitetas</div>\n      <div class=\"kurss-example\">die Polizei — policija</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Dažnai DAS</h4>\n    <p class=\"artikuli-explain\">DAS dažnai vartojamas su mažybiniais žodžiais su -chen / -lein, daugeliu žodžių su -ment / -um ir veiksmažodžiais, vartojamais kaip daiktavardžiai.</p>\n\n    <h5 class=\"artikuli-subtitle\">Taisyklės</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metalai → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">cheminiai elementai → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">viešbučiai → das Hotel</div>\n      <div class=\"kurss-example\">spalvos kaip daiktavardžiai → das Rot, das Blau</div>\n      <div class=\"kurss-example\">veiksmažodis kaip daiktavardis → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">veiksmažodžiai kaip daiktavardžiai → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Pavyzdžiai</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — vaikas</div>\n      <div class=\"kurss-example\">das Mädchen — mergaitė</div>\n      <div class=\"kurss-example\">das Häuschen — namelis</div>\n      <div class=\"kurss-example\">das Instrument — instrumentas</div>\n      <div class=\"kurss-example\">das Zentrum — centras</div>\n      <div class=\"kurss-example\">das Museum — muziejus</div>\n      <div class=\"kurss-example\">das Essen — valgymas / maistas</div>\n      <div class=\"kurss-example\">das Lernen — mokymasis</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Svarbios išimtys / mokykis su artikeliu</h4>\n    <p class=\"artikuli-explain\">Kai kurių žodžių artikelio negalima patikimai nustatyti pagal galūnę ar lietuvių kalbos giminę. Juos geriausia mokytis kartu su artikeliu.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — durys</div>\n      <div class=\"kurss-example\">das Messer — peilis</div>\n      <div class=\"kurss-example\">die Sonne — saulė</div>\n      <div class=\"kurss-example\">der Mond — mėnulis</div>\n      <div class=\"kurss-example\">das Mädchen — mergaitė</div>\n      <div class=\"kurss-example\">das Auto — automobilis</div>\n      <div class=\"kurss-example\">der Käse — sūris</div>\n      <div class=\"kurss-example\">die Gabel — šakutė</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Galūnės ir žodžių grupės padeda atspėti artikelį, bet tai nėra 100% patikima taisyklė. Jei nesi tikras, mokykis žodį kartu su artikeliu.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Įvardžiai</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ ir Dativ — įvardžių formos.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — kas?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — aš</div><div class=\"kurss-example\">du — tu</div><div class=\"kurss-example\">er — jis</div><div class=\"kurss-example\">sie — ji</div><div class=\"kurss-example\">es — tai</div><div class=\"kurss-example\">wir — mes</div><div class=\"kurss-example\">ihr — jūs</div><div class=\"kurss-example\">sie — jie / jos</div><div class=\"kurss-example\">Sie — Jūs (mandagiai)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — ką?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mane</div><div class=\"kurss-example\">dich — tave</div><div class=\"kurss-example\">ihn — jį (vyr. g.)</div><div class=\"kurss-example\">sie — ją (mot. g.)</div><div class=\"kurss-example\">es — tai</div><div class=\"kurss-example\">uns — mus</div><div class=\"kurss-example\">euch — jus</div><div class=\"kurss-example\">sie — juos / jas</div><div class=\"kurss-example\">Sie — Jus (mandagiai)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — kam?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — man</div><div class=\"kurss-example\">dir — tau</div><div class=\"kurss-example\">ihm — jam / tam</div><div class=\"kurss-example\">ihr — jai</div><div class=\"kurss-example\">uns — mums</div><div class=\"kurss-example\">euch — jums</div><div class=\"kurss-example\">ihnen — jiems / joms</div><div class=\"kurss-example\">Ihnen — Jums (mandagiai)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Kaip pasirinkti formą?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — sakinio veiksnys (kas daro?)</li><li><span class=\"case-red\">Akkusativ</span> — tiesioginis papildinys (ką?)</li><li><span class=\"case-green\">Dativ</span> — netiesioginis papildinys (kam?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Pavyzdžiai</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Aš tave matau.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Aš jį matau.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Jūs mums patinkate.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Aš tau padedu.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Aš duodu jam knygą.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Mes jums dėkojame.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ visada yra sakinio veiksnys, o Akkusativ ir Dativ — papildiniai. Žiūrėk į veiksmažodį ir klausk: <span class=\"case-red\">ką?</span> ar <span class=\"case-green\">kam?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Balsės — ilgos ir trumpos</h3>\n            <p class=\"kurss-lesson-intro\">Vokiečių kalboje balsės gali būti ilgos arba trumpos. Tai turi įtakos žodžio tarimui.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ilgoji balsė</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — šiltas</div><div class=\"kurss-example\">gut (gūt) — geras</div><div class=\"kurss-example\">Tat (tāt) — darbas / poelgis</div><div class=\"kurss-example\">Flur (flūr) — koridorius</div><div class=\"kurss-example\">Weg (vėk) — kelias</div><div class=\"kurss-example\">Hut (hūt) — skrybėlė</div><div class=\"kurss-example\">Hof (hōf) — kiemas</div><div class=\"kurss-example\">Schlaf (šlāf) — miegas</div></div>\n              <p>Jei po balsės eina viena priebalsė, balsė dažnai tariama ilgai.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Trumpoji balsė</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilc) — grybas</div><div class=\"kurss-example\">Wort (vort) — žodis</div><div class=\"kurss-example\">Mund (munt) — burna</div><div class=\"kurss-example\">bald (balt) — greitai / netrukus</div><div class=\"kurss-example\">scharf (šarf) — aštrus</div><div class=\"kurss-example\">Feld (felt) — laukas</div><div class=\"kurss-example\">voll (fol) — pilnas</div></div>\n              <p>Jei po balsės eina dvi ar daugiau priebalsių, balsė dažnai tariama trumpai.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Galūnės en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zingen) — dainuoti</div><div class=\"kurss-example\">tragen (trāgen) — nešti</div><div class=\"kurss-example\">Garten (garten) — sodas</div><div class=\"kurss-example\">Vogel (fōgel) — paukštis</div><div class=\"kurss-example\">Segel (zėgel) — burė</div><div class=\"kurss-example\">Braten (brāten) — kepsnys</div><div class=\"kurss-example\">Bogen (bōgen) — lankas</div><div class=\"kurss-example\">Spiegel (špygel) — veidrodis</div><div class=\"kurss-example\">Finger (finger) — pirštas</div><div class=\"kurss-example\">Halter (halter) — laikiklis</div><div class=\"kurss-example\">Arbeiter (arbaiter) — darbininkas</div><div class=\"kurss-example\">Häuser (hoizer) — namai</div><div class=\"kurss-example\">wieder (vyder) — vėl</div><div class=\"kurss-example\">breiter (braiter) — platesnis</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Raidė h kaip ilgumo ženklas</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rāmen) — rėmas</div><div class=\"kurss-example\">Ohr (ōr) — ausis</div><div class=\"kurss-example\">Kohle (kōle) — anglis</div><div class=\"kurss-example\">Zahl (cāl) — skaičius</div><div class=\"kurss-example\">ihn (yn) — jį</div><div class=\"kurss-example\">ihm (ym) — jam</div><div class=\"kurss-example\">Huhn (hūn) — višta</div><div class=\"kurss-example\">nahm (nām) — ėmė</div><div class=\"kurss-example\">nehmen (nėmen) — imti</div><div class=\"kurss-example\">Schuh (šū) — batas</div></div>\n              <p>Kai kuriuose žodžiuose h pailgina prieš ją esančią balsę. Tokiais atvejais h paprastai netariama.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Galūnės su e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lempa</div><div class=\"kurss-example\">Hase (hāze) — kiškis</div><div class=\"kurss-example\">Knabe (knābe) — berniukas</div><div class=\"kurss-example\">Rabe (rābe) — varnas</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ilgoji i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dy) — artikelis „die“</div><div class=\"kurss-example\">diese (dyze) — ši / šie</div><div class=\"kurss-example\">wieder (vyder) — vėl</div><div class=\"kurss-example\">Fliege (flyge) — musė</div><div class=\"kurss-example\">Ziege (cyge) — ožka</div><div class=\"kurss-example\">Stiel (štyl) — kotas</div><div class=\"kurss-example\">Dieb (dyp) — vagis</div><div class=\"kurss-example\">hier (hyr) — čia</div></div>\n              <p>Ilgoji i vokiečių kalboje dažnai rašoma kaip ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvigubos balsės</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zāl) — salė</div><div class=\"kurss-example\">Saat (zāt) — sėja / sėkla</div><div class=\"kurss-example\">Staat (štāt) — valstybė</div><div class=\"kurss-example\">Beere (bėre) — uoga</div><div class=\"kurss-example\">See (zė) — ežeras / jūra</div><div class=\"kurss-example\">Beet (bėt) — lysvė</div><div class=\"kurss-example\">Boot (bōt) — valtis</div><div class=\"kurss-example\">Moor (mōr) — pelkė</div><div class=\"kurss-example\">Moos (mōs) — samanos</div></div>\n              <p>Dvigubos balsės paprastai tariamos ilgai.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — siena</div><div class=\"kurss-example\">Wände (vende) — sienos</div><div class=\"kurss-example\">Vater (fāter) — tėvas</div><div class=\"kurss-example\">Väter (fėter) — tėvai</div><div class=\"kurss-example\">Schrank (šrank) — spinta</div><div class=\"kurss-example\">Schränke (šrenke) — spintos</div><div class=\"kurss-example\">Bank (bank) — suolas / bankas</div><div class=\"kurss-example\">Bänke (benke) — suolai</div><div class=\"kurss-example\">Tal (tāl) — slėnis</div><div class=\"kurss-example\">Täler (tėler) — slėniai</div></div>\n              <p>ä yra a umliautas.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōze) — rožė</div><div class=\"kurss-example\">Röschen (rėschen) — rožytė</div><div class=\"kurss-example\">Ofen (ōfen) — krosnis</div><div class=\"kurss-example\">Öfen (ėfen) — krosnys</div><div class=\"kurss-example\">Rock (rok) — sijonas</div><div class=\"kurss-example\">Röcke (reke) — sijonai</div></div>\n              <p>ö yra o umliautas.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurc) — trumpas</div><div class=\"kurss-example\">kürzer (kiurcer) — trumpesnis</div><div class=\"kurss-example\">Kunst (kunst) — menas</div><div class=\"kurss-example\">Künste (kiunste) — menai</div><div class=\"kurss-example\">Mutter (muter) — motina</div><div class=\"kurss-example\">Mütter (miuter) — motinos</div></div>\n              <p>ü yra u umliautas.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvibalsiai: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — medis</div><div class=\"kurss-example\">Bäume (boime) — medžiai</div><div class=\"kurss-example\">Haus (haus) — namas</div><div class=\"kurss-example\">Häuser (hoizer) — namai</div><div class=\"kurss-example\">Strauch (štrauch) — krūmas</div><div class=\"kurss-example\">Sträucher (štroicher) — krūmai</div><div class=\"kurss-example\">Maus (maus) — pelė</div><div class=\"kurss-example\">Mäuse (moize) — pelės</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvibalsiai: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hoite) — šiandien</div><div class=\"kurss-example\">Leute (loite) — žmonės</div><div class=\"kurss-example\">neu (noi) — naujas</div><div class=\"kurss-example\">neun (noin) — devyni</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvibalsiai: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — mano</div><div class=\"kurss-example\">dein (dain) — tavo</div><div class=\"kurss-example\">sein (zain) — jo / jos / būti</div><div class=\"kurss-example\">frei (frai) — laisvas</div><div class=\"kurss-example\">arbeiten (arbaiten) — dirbti</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>2-osios pamokos tarimo pastabos</h4>\n              <ul class=\"kurss-summary-list\"><li>žodžiuose ich, nicht, rechnen, zeichnen „ch“ tariama minkštai</li><li>žodžiuose arbeiten ir zeichnen „ei“ tariama kaip „ai“</li><li>„sp“ žodžio pradžioje tariama kaip „šp“</li><li>veiksmažodyje tun raidė „u“ tariama ilgai</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Santrauka</h4>\n              <ul class=\"kurss-summary-list\"><li>viena priebalsė po balsės → dažnai ilgoji balsė</li><li>dvi ar daugiau priebalsių → dažnai trumpoji balsė</li><li>h gali pailginti balsę</li><li>ie dažnai reiškia ilgąją i</li><li>dvigubos balsės paprastai būna ilgos</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Priebalsės ir raidžių junginiai</h3>\n            <p class=\"kurss-lesson-intro\">Vokiečių kalboje kai kurios priebalsės ir raidžių junginiai tariami kitaip, nei rašomi. Šioje pamokoje pateikti svarbiausi pavyzdžiai pradedančiajam.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Priebalsės</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rāt) — ratas</div><div class=\"kurss-example\">die Räder (rėder) — ratai</div><div class=\"kurss-example\">Bad (bāt) — vonia</div><div class=\"kurss-example\">Bäder (bėder) — vonios</div></div>\n              <p>Žodžio gale priebalsės dažnai tariamos ne taip, kaip rašomos.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>„ch“ gali būti tariama minkštai arba kietai. Kai kuriuose žodžiuose ji skamba kaip minkšta lietuviška „ch“ (kaip žodyje „chemija“), kituose – kiečiau, artimiau „k“ (kaip žodyje „choras“).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rechnen) — skaičiuoti</div><div class=\"kurss-example\">zeichnen (caichnen) — piešti</div><div class=\"kurss-example\">nicht (nicht) — ne</div><div class=\"kurss-example\">schlecht (šlecht) — blogas</div><div class=\"kurss-example\">mich (mich) — mane</div><div class=\"kurss-example\">dich (dich) — tave</div><div class=\"kurss-example\">Strauch (štrauch) — krūmas</div><div class=\"kurss-example\">noch (noch) — dar</div><div class=\"kurss-example\">Nacht (nacht) — naktis</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>„sch“ vokiečių kalboje tariama kaip lietuviška „š“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (šūle) — mokykla</div><div class=\"kurss-example\">Schüler (šiūler) — mokinys</div><div class=\"kurss-example\">Schiff (šif) — laivas</div><div class=\"kurss-example\">Schraube (šraube) — varžtas</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp ir st žodžio pradžioje</h4>\n              <p>Žodžio ar skiemens pradžioje „sp“ dažnai tariama kaip „šp“, o „st“ – kaip „št“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (špylen) — žaisti</div><div class=\"kurss-example\">Sprung (šprung) — šuolis</div><div class=\"kurss-example\">stehen (štėen) — stovėti</div><div class=\"kurss-example\">Stall (štal) — tvartas</div><div class=\"kurss-example\">Stand (štant) — padėtis / vieta</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>„qu“ vokiečių kalboje paprastai tariama kaip „kv“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvāl) — kančia</div><div class=\"kurss-example\">Quartier (kvartyr) — kvartalas / apsistojimo vieta</div><div class=\"kurss-example\">quer (kvėr) — skersai</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s ir z</h4>\n              <p>Žodžio pradžioje „s“ dažnai skamba kaip „z“. Raidė „z“ vokiečių kalboje skamba kaip lietuviška „c“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zāgen) — sakyti</div><div class=\"kurss-example\">singen (zingen) — dainuoti</div><div class=\"kurss-example\">Rose (rōze) — rožė</div><div class=\"kurss-example\">Zahl (cāl) — skaičius</div><div class=\"kurss-example\">Zeit (cait) — laikas</div><div class=\"kurss-example\">Zink (cink) — cinkas</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>Vokiečių kalboje „v“ dažnai tariama kaip „f“. Tarptautiniuose žodžiuose ji dažnai skamba kaip lietuviška „v“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fāter) — tėvas</div><div class=\"kurss-example\">von (fon) — nuo / iš</div><div class=\"kurss-example\">viel (fyl) — daug</div><div class=\"kurss-example\">vier (fyr) — keturi</div><div class=\"kurss-example\">Villa (vila) — vila</div><div class=\"kurss-example\">Klavier (klavyr) — fortepijonas</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x ir y</h4>\n              <p>„x“ tariama kaip „ks“. „y“ kai kuriuose žodžiuose tariama kaip „ü“ (panašiai kaip „iu“).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fėliks) — Feliksas</div><div class=\"kurss-example\">Axt (akst) — kirvis</div><div class=\"kurss-example\">Mystik (miustik) — mistika</div><div class=\"kurss-example\">Mythe (miūte) — mitas</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>„ß“ vokiečių kalboje tariama kaip „s“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fūs) — pėda</div><div class=\"kurss-example\">Füße (fiūse) — pėdos</div><div class=\"kurss-example\">Grüße (griūse) — linkėjimai / sveikinimai</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Santrauka</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → š</li><li>sp / st pradžioje → šp / št</li><li>qu → kv</li><li>z → c</li><li>v dažnai → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Veiksmažodžių pagrindai</h3>\n            <p class=\"kurss-lesson-intro\">1-osios pamokos veiksmažodžiai ir jų formos (asmenavimas)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Veiksmažodžiai</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — ateiti</div><div class=\"kurss-example\">gehen — eiti</div><div class=\"kurss-example\">stehen — stovėti</div><div class=\"kurss-example\">singen — dainuoti</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — aš ateinu</div><div class=\"kurss-example\">du kommst — tu ateini</div><div class=\"kurss-example\">er kommt — jis ateina</div><div class=\"kurss-example\">sie kommt — ji ateina</div><div class=\"kurss-example\">wir kommen — mes ateiname</div><div class=\"kurss-example\">ihr kommt — jūs ateinate</div><div class=\"kurss-example\">sie kommen — jie / jos ateina</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — aš einu</div><div class=\"kurss-example\">du gehst — tu eini</div><div class=\"kurss-example\">er geht — jis eina</div><div class=\"kurss-example\">sie geht — ji eina</div><div class=\"kurss-example\">wir gehen — mes einame</div><div class=\"kurss-example\">ihr geht — jūs einate</div><div class=\"kurss-example\">sie gehen — jie / jos eina</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — aš stoviu</div><div class=\"kurss-example\">du stehst — tu stovi</div><div class=\"kurss-example\">er steht — jis stovi</div><div class=\"kurss-example\">sie steht — ji stovi</div><div class=\"kurss-example\">wir stehen — mes stovime</div><div class=\"kurss-example\">ihr steht — jūs stovite</div><div class=\"kurss-example\">sie stehen — jie / jos stovi</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — aš dainuoju</div><div class=\"kurss-example\">du singst — tu dainuoji</div><div class=\"kurss-example\">er singt — jis dainuoja</div><div class=\"kurss-example\">sie singt — ji dainuoja</div><div class=\"kurss-example\">wir singen — mes dainuojame</div><div class=\"kurss-example\">ihr singt — jūs dainuojate</div><div class=\"kurss-example\">sie singen — jie / jos dainuoja</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>2-osios pamokos veiksmažodžiai</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — žaisti</div><div class=\"kurss-example\">arbeiten — dirbti</div><div class=\"kurss-example\">fragen — klausti</div><div class=\"kurss-example\">antworten — atsakyti</div><div class=\"kurss-example\">rechnen — skaičiuoti</div><div class=\"kurss-example\">zeichnen — piešti</div><div class=\"kurss-example\">tun — daryti</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — aš žaidžiu</div><div class=\"kurss-example\">du spielst — tu žaidi</div><div class=\"kurss-example\">er spielt — jis žaidžia</div><div class=\"kurss-example\">sie spielt — ji žaidžia</div><div class=\"kurss-example\">wir spielen — mes žaidžiame</div><div class=\"kurss-example\">ihr spielt — jūs žaidžiate</div><div class=\"kurss-example\">sie spielen — jie / jos žaidžia</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — aš dirbu</div><div class=\"kurss-example\">du arbeitest — tu dirbi</div><div class=\"kurss-example\">er arbeitet — jis dirba</div><div class=\"kurss-example\">sie arbeitet — ji dirba</div><div class=\"kurss-example\">wir arbeiten — mes dirbame</div><div class=\"kurss-example\">ihr arbeitet — jūs dirbate</div><div class=\"kurss-example\">sie arbeiten — jie / jos dirba</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — aš klausiu</div><div class=\"kurss-example\">du fragst — tu klausi</div><div class=\"kurss-example\">er fragt — jis klausia</div><div class=\"kurss-example\">sie fragt — ji klausia</div><div class=\"kurss-example\">wir fragen — mes klausiame</div><div class=\"kurss-example\">ihr fragt — jūs klausiate</div><div class=\"kurss-example\">sie fragen — jie / jos klausia</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — aš atsakau</div><div class=\"kurss-example\">du antwortest — tu atsakai</div><div class=\"kurss-example\">er antwortet — jis atsako</div><div class=\"kurss-example\">sie antwortet — ji atsako</div><div class=\"kurss-example\">wir antworten — mes atsakome</div><div class=\"kurss-example\">ihr antwortet — jūs atsakote</div><div class=\"kurss-example\">sie antworten — jie / jos atsako</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — aš skaičiuoju</div><div class=\"kurss-example\">du rechnest — tu skaičiuoji</div><div class=\"kurss-example\">er rechnet — jis skaičiuoja</div><div class=\"kurss-example\">sie rechnet — ji skaičiuoja</div><div class=\"kurss-example\">wir rechnen — mes skaičiuojame</div><div class=\"kurss-example\">ihr rechnet — jūs skaičiuojate</div><div class=\"kurss-example\">sie rechnen — jie / jos skaičiuoja</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — aš piešiu</div><div class=\"kurss-example\">du zeichnest — tu pieši</div><div class=\"kurss-example\">er zeichnet — jis piešia</div><div class=\"kurss-example\">sie zeichnet — ji piešia</div><div class=\"kurss-example\">wir zeichnen — mes piešiame</div><div class=\"kurss-example\">ihr zeichnet — jūs piešiate</div><div class=\"kurss-example\">sie zeichnen — jie / jos piešia</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — aš darau</div><div class=\"kurss-example\">du tust — tu darai</div><div class=\"kurss-example\">er tut — jis daro</div><div class=\"kurss-example\">sie tut — ji daro</div><div class=\"kurss-example\">wir tun — mes darome</div><div class=\"kurss-example\">ihr tut — jūs darote</div><div class=\"kurss-example\">sie tun — jie / jos daro</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Sakinio sandara</h3>\n            <p class=\"kurss-lesson-intro\">Klausiamajame sakinyje veiksmažodis vokiečių kalboje paprastai būna pirmoje vietoje.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Pavyzdžiai</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Tu ateini.</div><div class=\"kurss-example\">Kommst du? — Ar tu ateini?</div><div class=\"kurss-example\">Er singt. — Jis dainuoja.</div><div class=\"kurss-example\">Singt er? — Ar jis dainuoja?</div><div class=\"kurss-example\">Stehst du? — Ar tu stovi?</div><div class=\"kurss-example\">Ja, ich stehe. — Taip, aš stoviu.</div><div class=\"kurss-example\">Geht ihr? — Ar jūs einate?</div><div class=\"kurss-example\">Ja, wir gehen. — Taip, mes einame.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Klausimai su „was“</h4>\n              <p>Jei klausimas prasideda klausiamuoju žodžiu, veiksmažodis vokiečių kalboje paprastai būna iškart po klausiamojo žodžio.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Ką tu darai?</div><div class=\"kurss-example\">Was tut er? — Ką jis daro?</div><div class=\"kurss-example\">Was tut sie? — Ką ji daro?</div><div class=\"kurss-example\">Was tun sie? — Ką jie / jos daro?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Neiginys su „nicht“</h4>\n              <p>Jei neiginys „nicht“ susijęs su veiksmažodžiu, vokiečių kalboje jis paprastai būna po veiksmažodžio.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Aš nežaidžiu.</div><div class=\"kurss-example\">Paul fragt nicht. — Paulius neklausia.</div><div class=\"kurss-example\">Er kommt nicht. — Jis neateina.</div><div class=\"kurss-example\">Sie singen nicht. — Jie / jos nedainuoja.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Sakiniai iš 2-osios pamokos</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Ar tu žaidi?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Ne, aš nežaidžiu, aš dirbu.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paulius neklausia, jis dirba.</div><div class=\"kurss-example\">Arbeitest du? — Ar tu dirbi?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Ne, aš nedirbu, aš dainuoju.</div><div class=\"kurss-example\">Was tut Paul? — Ką daro Paulius?</div><div class=\"kurss-example\">Er spielt. — Jis žaidžia.</div><div class=\"kurss-example\">Was tut Marie? — Ką daro Marija?</div><div class=\"kurss-example\">Sie singt. — Ji dainuoja.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paulius žaidžia, o Marija dainuoja.</div><div class=\"kurss-example\">Singt ihr? — Ar jūs dainuojate?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Ne, mes nedainuojame, mes dirbame.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Ką daro Paulius ir Marija?</div><div class=\"kurss-example\">Sie fragen. — Jie klausia.</div><div class=\"kurss-example\">Sie antworten nicht. — Jie neatsako.</div><div class=\"kurss-example\">Wer arbeitet? — Kas dirba?</div><div class=\"kurss-example\">Wir arbeiten. — Mes dirbame.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Mes skaičiuojame ir piešiame.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Jie / jos ateina, klausia, atsako, dirba, žaidžia, dainuoja ir eina.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>2 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Antroji pamoka: dialogai, žodžiai, tarimas, gramatika ir vertimas.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — žaisti; groti</div>\n                  <div class=\"kurss-example\">nein — ne</div>\n                  <div class=\"kurss-example\">nicht — ne</div>\n                  <div class=\"kurss-example\">arbeiten — dirbti</div>\n                  <div class=\"kurss-example\">fragen — klausti</div>\n                  <div class=\"kurss-example\">was tut er? — ką jis daro?</div>\n                  <div class=\"kurss-example\">was tun sie? — ką jie / jos daro?</div>\n                  <div class=\"kurss-example\">aber — bet</div>\n                  <div class=\"kurss-example\">antworten — atsakyti</div>\n                  <div class=\"kurss-example\">rechnen — skaičiuoti, apskaičiuoti</div>\n                  <div class=\"kurss-example\">zeichnen — piešti</div>\n                  <div class=\"kurss-example\">Marie — Marija</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Žodžiuose ich, nicht, rechnen, zeichnen garsas ch tariamas minkštai, panašiai kaip lietuviškas ch prieš i ar e, pvz., žodžiuose: chemija, chirurgas.</div><div class=\"kurss-example\">Žodžiuose arbeiten, zeichnen dvibalsis ei tariamas panašiai kaip lietuviškas ai, pvz., žodyje laikas.</div><div class=\"kurss-example\">Priebalsių junginys sp tariamas kaip šp: spielen (špylen).</div><div class=\"kurss-example\">Veiksmažodyje tun balsis u visuose asmenyse tariamas ilgai.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Galūnės su e</h4>\n                  <div class=\"lesson1-grammar-note\">Jei veiksmažodžio kamienas baigiasi t, d, chn, tai asmenuojant prieš galūnes -st ir -t įterpiamas e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Klausiamasis žodis</h4>\n                  <div class=\"lesson1-grammar-note\">Klausiamuosiuose sakiniuose, kurie prasideda klausiamuoju žodžiu, pvz.: ką? kas? kuris? kodėl? dėl ko? ir t. t., veiksmažodis eina iškart po klausiamojo žodžio.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Ką tu darai?</div><div class=\"kurss-example\">Was tut er? — Ką jis daro?</div><div class=\"kurss-example\">Was tut sie? — Ką ji daro?</div><div class=\"kurss-example\">Was tun sie? — Ką jie / jos daro?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Neiginys su nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Jei neiginys nicht susijęs su veiksmažodžiu, neiginio žodis eina po veiksmažodžio.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Jis neateina.</div><div class=\"kurss-example\">Sie singen nicht. — Jie nedainuoja.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"2 pamoka: vertimo kortelė\">\n                    <span class=\"lesson1-training-progress\">2 pamoka · Išversk: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kas klausia?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vertimą į vokiečių kalbą. Atsakius kitas spustelėjimas parodo kitą kortelę.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>6 pamoka</h3>\n    <p class=\"kurss-lesson-intro\">Skaitvardžiai, daugiskaita, umliautai ir daiktavardžių daugiskaitos formos.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — yra, guli</div><div class=\"kurss-example\">der Bleistift (blaištift) — pieštukas</div><div class=\"kurss-example\">einige (ainige) — keli</div><div class=\"kurss-example\">hinlegen — padėti</div><div class=\"kurss-example\">legt hin — padeda</div><div class=\"kurss-example\">wieder (vyder) — vėl</div><div class=\"kurss-example\">aufmachen — atidaryti</div><div class=\"kurss-example\">er macht auf — jis atidaro</div><div class=\"kurss-example\">anspitzen (anšpicen) — padrožti</div><div class=\"kurss-example\">er spitzt an — jis padrožia</div><div class=\"kurss-example\">sich setzen — atsisėsti</div><div class=\"kurss-example\">setzt sich — atsisėda</div><div class=\"kurss-example\">der Schlüssel (šliusel) — raktas</div><div class=\"kurss-example\">das Fenster (fenster) — langas</div><div class=\"kurss-example\">die Tafel (dy tafel) — lenta</div><div class=\"kurss-example\">der Garten — sodas</div><div class=\"kurss-example\">der Löffel — šaukštas</div><div class=\"kurss-example\">zählen (cėlen) — skaičiuoti</div><div class=\"kurss-example\">die Nadel — adata</div><div class=\"kurss-example\">was ist das — kas tai?</div><div class=\"kurss-example\">der Hammer — kūjis</div><div class=\"kurss-example\">die Hämmer — kūjai</div><div class=\"kurss-example\">der Deckel (dėr dekel) — dangtis</div><div class=\"kurss-example\">der Teller — lėkštė</div><div class=\"kurss-example\">der Wagen — vežimas</div><div class=\"kurss-example\">der Schlitten — rogės</div><div class=\"kurss-example\">das Ding — daiktas</div><div class=\"kurss-example\">die Dinge — daiktai</div><div class=\"kurss-example\">wie sind die Dinge? — kokie yra daiktai?</div><div class=\"kurss-example\">voll (fol) — pilnas</div><div class=\"kurss-example\">leer (lėr) — tuščias</div><div class=\"kurss-example\">schwer (švėr) — sunkus</div><div class=\"kurss-example\">leicht — lengvas</div><div class=\"kurss-example\">der Eimer — kibiras</div><div class=\"kurss-example\">wieviel (vyfyl) — kiek</div><div class=\"kurss-example\">wieviel Nadeln — kiek adatų</div><div class=\"kurss-example\">hier (hyr) — čia</div><div class=\"kurss-example\">dort — ten</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä yra balsio a umliautas ir tariamas kaip trumpas arba ilgas e.</div><div class=\"kurss-example\">Pavyzdžiai: das Mädchen (mėtchen), die Bänke (dy benke), der Vater (dėr fater), die Väter (dy fėter).</div><div class=\"kurss-example\">ü yra balsio u umliautas. Tariant jį, lūpas reikia stipriai suapvalinti ir apvaliomis lūpomis bandyti ištarti i.</div><div class=\"kurss-example\">Pavyzdžiai: fünf, der Schlüssel (šliusel).</div><div class=\"kurss-example\">ö tariamas apvaliomis lūpomis, bandant ištarti e: der Löffel.</div><div class=\"kurss-example\">Dvigubas balsis žymi ilgą balsį: leer (lėr).</div><div class=\"kurss-example\">Dvibalsis eu tariamas kaip oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramatika ir paaiškinimai</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Esamajame laike kirčiuotas sudurtinio veiksmažodžio priešdėlis atsiskiria nuo veiksmažodžio ir eina sakinio gale.</div><div class=\"kurss-example\">Pavyzdžiai: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Skaitvardis vienas, vartojamas su daiktavardžiu, turi formas visoms trims giminėms: vyriškoji giminė ein, moteriškoji giminė eine, bevardė giminė ein.</div><div class=\"kurss-example\">Pavyzdžiai: ein Schüler — vienas mokinys; eine Schülerin — viena mokinė; ein Kind — vienas vaikas.</div><div class=\"kurss-example\">Skaitvardžiai: eins, zwei, drei, vier (fyr), fünf, sechs (zeks), sieben (zyben), acht, neun (noin), zehn (cėn).</div><div class=\"kurss-example\">Vokiečių kalboje jungtis turi vienaskaitos ir daugiskaitos formą: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Lietuvių kalboje tokiuose sakiniuose vartojamas nekaitomas parodomasis žodis tai, ir vokiečių kalboje taip pat vartojama viena forma: das.</div><div class=\"kurss-example\">Pavyzdžiai: tai kūjis — das ist ein Hammer; tai adata — das ist eine Nadel; tai kūjai — das sind Hämmer; tai adatos — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — vežimas ir der Schlitten — rogės: lietuvių kalboje žodis rogės vartojamas tik daugiskaita, o vokiečių kalboje abu žodžiai vartojami ir vienaskaita, ir daugiskaita.</div><div class=\"kurss-example\">Vyriškosios ir bevardės giminės daiktavardžiai su galūne -er, -el, -en daugiskaitoje dažnai negauna galūnės.</div><div class=\"kurss-example\">Pavyzdžiai: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Moteriškosios giminės daiktavardžiai su galūne -el, -er daugiskaitoje gauna -n.</div><div class=\"kurss-example\">Pavyzdžiai: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Išimtys: die Mutter (motina) — die Mütter (motinos); die Tochter (dukra) — die Töchter (dukros).</div><div class=\"kurss-example\">Nežymimasis artikelis daugiskaitos neturi: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Tiesioginiame sakinyje veiksmažodinis tarinys eina antroje vietoje: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"6 pamoka: vertimo kortelė\"><span class=\"lesson1-training-progress\">6 pamoka · Išversk: 1 / 21</span><span class=\"lesson1-training-text\">Paul ima pieštuką ir piešia.</span></button><p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vertimą į vokiečių kalbą. Atsakius kitas spustelėjimas parodo kitą kortelę.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>5 pamoka</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, galininkas, sitzen, fragen ir galūnė -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zicen) — sėdėti</div>\n        <div class=\"kurss-example\">fragen (fragen) — klausti</div>\n        <div class=\"kurss-example\">der Lehrer (dėr lėrer) — mokytojas</div>\n        <div class=\"kurss-example\">gut (gūt) — gerai</div>\n        <div class=\"kurss-example\">wen (vėn) — ką</div>\n        <div class=\"kurss-example\">loben — girti</div>\n        <div class=\"kurss-example\">der Schüler (šiūler) — mokinys</div>\n        <div class=\"kurss-example\">klein — mažas</div>\n        <div class=\"kurss-example\">groß (gros) — didelis</div>\n        <div class=\"kurss-example\">die Lehrerin — mokytoja</div>\n        <div class=\"kurss-example\">die Schülerin — mokinė</div>\n        <div class=\"kurss-example\">schlecht (šlecht) — blogai</div>\n        <div class=\"kurss-example\">tadeln — peikti</div>\n        <div class=\"kurss-example\">oder (oder) — arba</div>\n        <div class=\"kurss-example\">das Kind (kint) — vaikas</div>\n        <div class=\"kurss-example\">artig (artich) — paklusnus</div>\n        <div class=\"kurss-example\">die Mutter — motina</div>\n        <div class=\"kurss-example\">lieben (lyben) — mylėti</div>\n        <div class=\"kurss-example\">der Vater (fater) — tėvas</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz yra dvigubas z ir tariamas kaip vokiškas z, t. y. lietuviškas c: sitzen (zicen).</div>\n        <div class=\"kurss-example\">v vokiškuose žodžiuose tariamas kaip f: der Vater (fater).</div>\n        <div class=\"kurss-example\">ß vadinama escet ir tariama kaip lietuviškas s: groß (gros), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Vardininkas ir galininkas</h4><div class=\"lesson1-grammar-note\">Lietuvių kalboje vardininkas atsako į klausimą kas?, o galininkas – į klausimą ką?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vokiečių kalboje vardininko klausimas yra wer? asmenims ir was? daiktams.</div><div class=\"kurss-example\">Galininko klausimas yra wen? asmenims ir was? daiktams.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Artikelio kaita galininke</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + galininkas</h4><div class=\"lesson1-grammar-note\">Vokiečių kalboje veiksmažodis fragen reikalauja galininko.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Galūnė -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Daug moteriškosios giminės žodžių sudaroma su galūne -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Veiksmažodžio vieta</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Tiesioginiame sakinyje veiksmažodis eina antroje vietoje.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"5 pamoka: vertimo kortelė\"><span class=\"lesson1-training-progress\">5 pamoka · Išversk: 1 / 16</span><span class=\"lesson1-training-text\">Ką myli tėvas?</span></button><p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vertimą į vokiečių kalbą. Atsakius kitas spustelėjimas parodo kitą kortelę.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>4 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Galininkas, nehmen, hinlegen, hinausgehen ir būdvardžiai.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nėmen) — imti</div><div class=\"kurss-example\">er nimmt (nimt) — jis ima</div><div class=\"kurss-example\">der Federhalter (dėr fėderhalter) — plunksnakotis</div><div class=\"kurss-example\">einen Federhalter — plunksnakotį</div><div class=\"kurss-example\">zeigen — rodyti</div><div class=\"kurss-example\">schwarz (švarc) — juodas</div><div class=\"kurss-example\">weiß (vais) — baltas</div><div class=\"kurss-example\">die Feder (dy fėder) — plunksna</div><div class=\"kurss-example\">eine Feder — plunksną</div><div class=\"kurss-example\">spitz (špic) — smailus</div><div class=\"kurss-example\">hinlegen — padėti</div><div class=\"kurss-example\">legt hin — padeda</div><div class=\"kurss-example\">das Mädchen (mėtchen) — mergaitė</div><div class=\"kurss-example\">das Messer — peilis</div><div class=\"kurss-example\">ein Messer — peilį</div><div class=\"kurss-example\">scharf — aštrus</div><div class=\"kurss-example\">stumpf (štumpf) — atšipęs, bukas</div><div class=\"kurss-example\">dann — tada</div><div class=\"kurss-example\">hinaus — laukan</div><div class=\"kurss-example\">hinausgehen — išeiti, eiti laukan</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Galūnės -en, -er, -el yra nekirčiuotos, todėl e šiose galūnėse vos girdimas: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">Vokiečių kalboje h gali būti ir garsas, ir prieš jį esančio balsio ilgumo ženklas.</div><div class=\"kurss-example\">Jei h žymi ilgumą, jis netariamas kaip garsas: nehmen (nėmen).</div><div class=\"kurss-example\">Jei po balsio eina tik vienas priebalsis, balsis tariamas ilgai: die (dy) Feder (fėder), den (dėn).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Galininkas</h4><div class=\"lesson1-grammar-note\">Moteriškosios ir bevardės giminės galininkas sutampa su vardininku. Keičiasi tik vyriškoji giminė.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Įvardžiai</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — vyriškoji giminė</div><div class=\"kurss-example\">sie — moteriškoji giminė</div><div class=\"kurss-example\">es — bevardė giminė</div><div class=\"kurss-example\">daugiskaitoje — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Skiriamieji veiksmažodžiai</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Būdvardžiai</h4><div class=\"lesson1-grammar-note\">Jei būdvardis sakinyje yra tarinys, jis nekinta nei gimine, nei skaičiumi.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Neiginys su nicht</h4><div class=\"lesson1-grammar-note\">Jei nicht neigia būdvardį, jis eina prieš neigiamą žodį.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Daiktavardžiai su galūne -chen ir -lein yra bevardės giminės: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"4 pamoka: vertimo kortelė\"><span class=\"lesson1-training-progress\">4 pamoka · Išversk: 1 / 16</span><span class=\"lesson1-training-text\">Mergaitė ima plunksnakotį.</span></button><p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vertimą į vokiečių kalbą. Atsakius kitas spustelėjimas parodo kitą kortelę.</p></div></div></details>",
  "kurssLesson3": "            <h3>3 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Trečioji pamoka: dialogai, žodžiai, tarimas, gramatika ir vertimas.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kas</div><div class=\"kurss-example\">was — kas</div><div class=\"kurss-example\">hier — čia</div><div class=\"kurss-example\">dort — ten</div><div class=\"kurss-example\">der Tisch — stalas</div><div class=\"kurss-example\">ein Tisch — stalas</div><div class=\"kurss-example\">die Bank — suolas</div><div class=\"kurss-example\">eine Bank — suolas</div><div class=\"kurss-example\">liegen — gulėti</div><div class=\"kurss-example\">liegt hier ein Buch? — ar čia yra / guli knyga?</div><div class=\"kurss-example\">das Buch — knyga</div><div class=\"kurss-example\">ein Buch — knyga</div><div class=\"kurss-example\">hängen — kaboti</div><div class=\"kurss-example\">das Bild — paveikslas</div><div class=\"kurss-example\">ein Bild — paveikslas</div><div class=\"kurss-example\">die Tafel — lenta</div><div class=\"kurss-example\">eine Tafel — lenta</div><div class=\"kurss-example\">wie — koks, kokia</div><div class=\"kurss-example\">ist — yra</div><div class=\"kurss-example\">dick — storas, riebus</div><div class=\"kurss-example\">das Heft — sąsiuvinis</div><div class=\"kurss-example\">ein Heft — sąsiuvinis</div><div class=\"kurss-example\">dünn — plonas, liesas</div><div class=\"kurss-example\">niedrig — žemas</div><div class=\"kurss-example\">hoch — aukštas</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ilgasis i garsas vokiečių kalboje žymimas ie: liegen (lygen), hier (hyr), wie (vy).</div><div class=\"kurss-example\">ck yra dvigubas k: dick (dikk).</div><div class=\"kurss-example\">Būdvardžių ir prieveiksmių galūnė -ig skamba kaip lengvas -ich: niedrig (nydrich).</div><div class=\"kurss-example\">Jei po -ig eina e, t. y. -ige, tai g tariamas kaip aiškus g garsas: niedrige (nydrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Veiksnys</h4><div class=\"lesson1-grammar-note\">Vokiečių kalboje veiksnys atsako į klausimą wer? / was? ir yra vardininko linksnio.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Klausimu wer? klausiama apie asmenis.</div><div class=\"kurss-example\">Klausimu was? klausiama apie daiktus.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artikeliai</h4><div class=\"lesson1-grammar-note\">Vokiečių kalboje daiktavardžiai turi 3 gimines: vyriškąją, moteriškąją ir bevardę. Prieš daiktavardžius paprastai eina žodelis, vadinamas artikeliu. Šis žodelis neverčiamas.</div><h5 class=\"lesson2-subtitle\">Žymimasis artikelis</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">vyriškoji giminė — der</div><div class=\"kurss-example\">moteriškoji giminė — die</div><div class=\"kurss-example\">bevardė giminė — das</div><div class=\"kurss-example\">Daugiskaitoje žymimasis artikelis visoms trims giminėms yra die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Nežymimasis artikelis</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">vyriškoji giminė — ein</div><div class=\"kurss-example\">moteriškoji giminė — eine</div><div class=\"kurss-example\">bevardė giminė — ein</div><div class=\"kurss-example\">Nežymimasis artikelis daugiskaitos neturi.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Tikriniai daiktavardžiai</h4><div class=\"lesson1-grammar-note\">Prieš tikrinius daiktavardžius artikelis nevartojamas.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Veiksmažodžio vieta</h4><div class=\"lesson1-grammar-note\">Tiesioginiame sakinyje veiksmažodis eina antroje vietoje.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vokiškai apie daiktus, kurie stovi vertikaliai, sakoma, kad daiktas stovi:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Apie daiktus, kurie yra horizontalioje padėtyje, sakoma, kad jie guli:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Daiktai taip pat gali kaboti:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"3 pamoka: vertimo kortelė\"><span class=\"lesson1-training-progress\">3 pamoka · Išversk: 1 / 22</span><span class=\"lesson1-training-text\">Ar tu skaičiuoji?</span></button><p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vertimą į vokiečių kalbą. Atsakius kitas spustelėjimas parodo kitą kortelę.</p></div></div></details>",
  "kurssLesson7": "            <h3>7 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Septintoji pamoka: liepiamoji nuosaka, kreipimosi forma ir daugiskaita.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — dainuoti</div><div class=\"kurss-example\">singe — dainuok</div><div class=\"kurss-example\">singt — dainuokite</div><div class=\"kurss-example\">singen Sie — dainuokite (mandagiai)</div><div class=\"kurss-example\">das Lied (das lyt) — daina</div><div class=\"kurss-example\">Sie — Jūs</div><div class=\"kurss-example\">zählen — skaičiuoti</div><div class=\"kurss-example\">das Fräulein (froilain) — panelė</div><div class=\"kurss-example\">der Müller — malūnininkas</div><div class=\"kurss-example\">öffnen — atidaryti</div><div class=\"kurss-example\">das Fenster (fenster) — langas</div><div class=\"kurss-example\">alle — visi</div><div class=\"kurss-example\">der Spiegel (špygel) — veidrodis</div><div class=\"kurss-example\">der Lappen — skuduras, šluostė</div><div class=\"kurss-example\">der Spaten — kastuvas</div><div class=\"kurss-example\">der Besen — šluota</div><div class=\"kurss-example\">die Schaufel — semtuvėlis</div><div class=\"kurss-example\">die Schüssel — dubuo</div><div class=\"kurss-example\">das Zimmer — kambarys</div><div class=\"kurss-example\">das Ufer (ūfer) — krantas</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp žodžio ar skiemens pradžioje tariamas kaip šp: der Spiegel (dėr špygel).</div><div class=\"kurss-example\">sch tariamas kaip lietuviškas š: die Schaufel (dy šaufel), die Schüssel (dy šiusel).</div><div class=\"kurss-example\">Dvibalsis äu tariamas kaip lietuviškas oi: das Fräulein (das froilain).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Liepiamoji nuosaka</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vienaskaitos 2 asmens liepiamoji nuosaka atitinka veiksmažodžio vienaskaitos 2 asmenį be asmens galūnės -st, pridedant galūnę -e.</div><div class=\"kurss-example\">Pavyzdžiai: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Labai dažnai galūnė -e nevartojama, todėl liepiamoji forma tampa vienskiemenė: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Daugiskaitos liepiamoji nuosaka</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Daugiskaitos 2 asmens liepiamoji forma sutampa su esamojo laiko daugiskaitos 2 asmeniu, bet vartojama be įvardžio.</div><div class=\"kurss-example\">Pavyzdžiai: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Mandagi kreipimosi forma su Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Mandagi kreipimosi forma „Jūs“ vokiečių kalboje atitinka daugiskaitos 3 asmenį. Įvardis Sie rašomas didžiąja raide ir eina po veiksmažodžio.</div><div class=\"kurss-example\">Pavyzdžiai: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Veiksmažodyje öffnen dėl lengvesnio tarimo vienaskaitos 2 ir 3 asmenyje bei daugiskaitos 2 asmenyje tarp kamieno ir galūnės įterpiamas e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Pratimas</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"7 pamoka: pratimo kortelė\"><span class=\"lesson1-training-progress\">7 pamoka · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — klausti</span></button><p class=\"lesson1-training-hint\">Paliesk kortelę, kad pamatytum liepiamosios nuosakos formas.</p></div></div></details>",
  "kurssLesson1": "            <h3>1 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Pirmoji pamoka: veiksmažodžiai esamuoju laiku, žodžiai, tarimas, gramatika ir vertimas.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Veiksmažodžiai esamuoju laiku</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Veiksmažodžiai ir jų asmenavimas esamuoju laiku.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — ateiti</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>aš ateinu</span><span>du</span><strong>kommst</strong><span>tu ateini</span><span>er / sie</span><strong>kommt</strong><span>jis / ji ateina</span><span>wir</span><strong>kommen</strong><span>mes ateiname</span><span>ihr</span><strong>kommt</strong><span>jūs ateinate</span><span>sie / Sie</span><strong>kommen</strong><span>jie ateina / Jūs ateinate</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — eiti</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>aš einu</span><span>du</span><strong>gehst</strong><span>tu eini</span><span>er / sie</span><strong>geht</strong><span>jis / ji eina</span><span>wir</span><strong>gehen</strong><span>mes einame</span><span>ihr</span><strong>geht</strong><span>jūs einate</span><span>sie / Sie</span><strong>gehen</strong><span>jie eina / Jūs einate</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — stovėti</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>aš stoviu</span><span>du</span><strong>stehst</strong><span>tu stovi</span><span>er / sie</span><strong>steht</strong><span>jis / ji stovi</span><span>wir</span><strong>stehen</strong><span>mes stovime</span><span>ihr</span><strong>steht</strong><span>jūs stovite</span><span>sie / Sie</span><strong>stehen</strong><span>jie stovi / Jūs stovite</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — dainuoti</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>aš dainuoju</span><span>du</span><strong>singst</strong><span>tu dainuoji</span><span>er / sie</span><strong>singt</strong><span>jis / ji dainuoja</span><span>wir</span><strong>singen</strong><span>mes dainuojame</span><span>ihr</span><strong>singt</strong><span>jūs dainuojate</span><span>sie / Sie</span><strong>singen</strong><span>jie dainuoja / Jūs dainuojate</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Pavyzdžiai</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Apytikslis žodžių tarimas pateiktas skliaustuose lietuviškomis raidėmis.<br>Tai galioja ir tolesnėse pamokose.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vyr) — mes</div><div class=\"kurss-example\">Žodyje „wir“ raidė i tariama ilgai.</div><div class=\"kurss-example\">kommen (komen) — ateiti</div><div class=\"kurss-example\">gehen (gė-en) — eiti</div><div class=\"kurss-example\">stehen (štė-en) — stovėti</div><div class=\"kurss-example\">singen (zingen) — dainuoti</div><div class=\"kurss-example\">du (dū) kommst — tu ateini</div><div class=\"kurss-example\">er (ėr) kommt — jis ateina</div><div class=\"kurss-example\">sie (zy) kommt — ji ateina</div><div class=\"kurss-example\">wer (vėr) — kas?</div><div class=\"kurss-example\">ja (ja) — taip</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Taisyklingas žodžių tarimas, užrašytas lietuviškomis raidėmis, pateikiamas pamokose.</div><div class=\"kurss-example\">Wir (vyr) — mes. Žodyje wir i visada tariama ilgai.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Bendratis</h4><div class=\"lesson1-grammar-note\">Pagrindinė veiksmažodžio forma. Vokiečių kalbos bendratis paprastai baigiasi -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Esamojo laiko galūnės</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Nuimk <span class=\"lesson1-ending-accent\">-en</span> nuo veiksmažodžio bendraties ir pridėk galūnę.</strong></p><p>Pavyzdys: kommen → komm + galūnė</p><div class=\"lesson1-ending-process\" aria-label=\"Esamojo laiko galūnių sudarymas\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>bendratis</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>nuimk <span class=\"lesson1-ending-accent\">-en</span></strong><span>lieka kamienas</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>kamienas</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>pridėk galūnę</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Pavyzdžiai</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Klausiamieji sakiniai</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Vokiečių kalbos klausiamajame sakinyje veiksmažodis paprastai perkeliamas į pirmą vietą.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Lietuviškai:<br>Tu ateini.<br>Ar tu ateini?</div><div class=\"kurss-example\">Vokiškai:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — tu ateini<br>kommst du? — ar tu ateini?</div><div class=\"kurss-example\">er singt — jis dainuoja<br>singt er? — ar jis dainuoja?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Asmenų skirtumas</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — jis ateina</div><div class=\"kurss-example\">sie kommt — ji ateina</div><div class=\"kurss-example\">sie kommen — jie / jos ateina</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"1 pamoka: treniruočių kortelė\">\n                    <span class=\"lesson1-training-progress\">1 pamoka · Išversk: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Ar tu ateini?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vertimą į vokiečių kalbą. Atsakius kitas spustelėjimas parodo kitą kortelę.</p>\n                </div>\n              </div>\n            </details>"
};

